using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync, nameof(WebSearchTool.SearchAsync),
        "Search the web for information on a topic. Returns a list of result titles, URLs, and snippets."),
    AIFunctionFactory.Create(notepad.AddNote, nameof(notepad.AddNote),
        "Save a research note. Use this to record important findings as you research."),
    AIFunctionFactory.Create(notepad.GetNotes, nameof(notepad.GetNotes),
        "Retrieve all saved research notes so far."),
};

// ---------------------------------------------------------------------------
// Agent setup
// ---------------------------------------------------------------------------
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research assistant that searches the web, takes notes, and summarizes findings.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = tools,
    },
});

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (MAF)           ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var systemPrompt = $"""
    You are a thorough research assistant. Your goal is to research the following
    topic and produce a well-organized summary.

    ## Research process
    1. Search the web for relevant information on the topic (perform 2-3 searches
       with different queries to get broad coverage).
    2. For each useful finding, save a note using the note-taking tool. Include
       the source URL in each note.
    3. After gathering enough information, retrieve all your notes.
    4. Produce a final summary that synthesizes your findings. Include:
       - An overview of the topic
       - Key facts and details
       - Different perspectives (if applicable)
       - A list of sources

    Topic to research: {topic}
    """;

var session = await agent.CreateSessionAsync();

var response = await agent.RunAsync(systemPrompt, session);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("               RESEARCH SUMMARY            ");
Console.WriteLine("═══════════════════════════════════════════\n");

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 })
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine($"Notes collected: {notepad.Count}");
Console.WriteLine("═══════════════════════════════════════════");

// ---------------------------------------------------------------------------
// Web Search Tool — uses DuckDuckGo Instant Answer API (no key required)
// ---------------------------------------------------------------------------
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";
            var json = await s_http.GetFromJsonAsync<JsonElement>(url);

            var results = new StringBuilder();
            results.AppendLine($"Search results for: \"{query}\"\n");

            // Abstract / instant answer
            var abstractText = json.TryGetProperty("AbstractText", out var at) ? at.GetString() : null;
            var abstractUrl = json.TryGetProperty("AbstractURL", out var au) ? au.GetString() : null;
            var abstractSource = json.TryGetProperty("AbstractSource", out var asrc) ? asrc.GetString() : null;

            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"## {abstractSource}");
                results.AppendLine(abstractText);
                results.AppendLine($"Source: {abstractUrl}\n");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                var count = 0;
                foreach (var item in topics.EnumerateArray())
                {
                    if (count >= 8) break;

                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = item.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : null;

                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(firstUrl))
                            results.AppendLine($"  URL: {firstUrl}");
                        count++;
                    }

                    // Handle sub-topics
                    if (item.TryGetProperty("Topics", out var subTopics) && subTopics.ValueKind == JsonValueKind.Array)
                    {
                        foreach (var sub in subTopics.EnumerateArray())
                        {
                            if (count >= 8) break;
                            var subText = sub.TryGetProperty("Text", out var st) ? st.GetString() : null;
                            var subUrl = sub.TryGetProperty("FirstURL", out var su) ? su.GetString() : null;

                            if (!string.IsNullOrWhiteSpace(subText))
                            {
                                results.AppendLine($"- {subText}");
                                if (!string.IsNullOrWhiteSpace(subUrl))
                                    results.AppendLine($"  URL: {subUrl}");
                                count++;
                            }
                        }
                    }
                }
            }

            // Definition
            var definition = json.TryGetProperty("Definition", out var def) ? def.GetString() : null;
            if (!string.IsNullOrWhiteSpace(definition))
            {
                var defSource = json.TryGetProperty("DefinitionURL", out var du) ? du.GetString() : null;
                results.AppendLine($"\nDefinition: {definition}");
                if (!string.IsNullOrWhiteSpace(defSource))
                    results.AppendLine($"Source: {defSource}");
            }

            var output = results.ToString();
            return string.IsNullOrWhiteSpace(output.Replace($"Search results for: \"{query}\"\n", "").Trim())
                ? $"No detailed results found for \"{query}\". Try a different or more specific query."
                : output;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

// ---------------------------------------------------------------------------
// Notepad Tool — in-memory note storage
// ---------------------------------------------------------------------------
class Notepad
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;

    public string AddNote(
        [Description("The content of the research note to save, including source URL if available")]
        string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"[Note {i + 1}]");
            sb.AppendLine(_notes[i]);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

